import java.util.*;

public class Codec {
    public String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        serializeHelper(root, sb);
        return sb.toString();
    }

    private void serializeHelper(TreeNode node, StringBuilder sb) {
        if (node == null) {
            sb.append("#,");
            return;
        }
        sb.append(node.val).append(",");
        serializeHelper(node.left, sb);
        serializeHelper(node.right, sb);
    }

    public TreeNode deserialize(String data) {
        Queue<String> queue = new LinkedList<>(Arrays.asList(data.split(",")));
        return deserializeHelper(queue);
    }

    private TreeNode deserializeHelper(Queue<String> queue) {
        String val = queue.poll();
        if ("#".equals(val)) {
            return null;
        }
        TreeNode node = new TreeNode(Integer.parseInt(val));
        node.left = deserializeHelper(queue);
        node.right = deserializeHelper(queue);
        return node;
    }
}

import java.util.*;

public class Codec {
    public String serialize(TreeNode root) {
        if (root == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node == null) {
                sb.append("#,");
            } else {
                sb.append(node.val).append(",");
                queue.offer(node.left);
                queue.offer(node.right);
            }
        }
        return sb.toString();
    }

    public TreeNode deserialize(String data) {
        if (data.isEmpty()) {
            return null;
        }
        String[] tokens = data.split(",");
        TreeNode root = new TreeNode(Integer.parseInt(tokens[0]));
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int i = 1;

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (!"#".equals(tokens[i])) {
                node.left = new TreeNode(Integer.parseInt(tokens[i]));
                queue.offer(node.left);
            }
            i++;
            if (!"#".equals(tokens[i])) {
                node.right = new TreeNode(Integer.parseInt(tokens[i]));
                queue.offer(node.right);
            }
            i++;
        }
        return root;
    }
}

import java.util.*;

public class Codec {
    public String serialize(TreeNode root) {
        List<String> tokens = new ArrayList<>();
        postorder(root, tokens);
        return String.join(",", tokens);
    }

    private void postorder(TreeNode node, List<String> tokens) {
        if (node == null) {
            tokens.add("#");
            return;
        }
        postorder(node.left, tokens);
        postorder(node.right, tokens);
        tokens.add(String.valueOf(node.val));
    }

    public TreeNode deserialize(String data) {
        if (data == null || data.isEmpty()) {
            return null;
        }
        String[] tokens = data.split(",");
        int[] index = new int[] {tokens.length - 1};
        return build(tokens, index);
    }

    private TreeNode build(String[] tokens, int[] index) {
        String token = tokens[index[0]--];
        if (token.equals("#")) {
            return null;
        }
        TreeNode node = new TreeNode(Integer.parseInt(token));
        node.right = build(tokens, index);
        node.left = build(tokens, index);
        return node;
    }
}

public class Codec {
    public String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        write(root, sb);
        return sb.toString();
    }

    private void write(TreeNode node, StringBuilder sb) {
        if (node == null) {
            sb.append('N');
            return;
        }
        sb.append('(').append(node.val).append(' ');
        write(node.left, sb);
        sb.append(' ');
        write(node.right, sb);
        sb.append(')');
    }

    public TreeNode deserialize(String data) {
        int[] index = new int[] {0};
        return read(data, index);
    }

    private TreeNode read(String data, int[] index) {
        if (data.charAt(index[0]) == 'N') {
            index[0]++;
            return null;
        }

        index[0]++;
        int sign = 1;
        if (data.charAt(index[0]) == '-') {
            sign = -1;
            index[0]++;
        }
        int value = 0;
        while (index[0] < data.length() && Character.isDigit(data.charAt(index[0]))) {
            value = value * 10 + data.charAt(index[0]) - '0';
            index[0]++;
        }

        TreeNode node = new TreeNode(sign * value);
        index[0]++;
        node.left = read(data, index);
        index[0]++;
        node.right = read(data, index);
        index[0]++;
        return node;
    }
}
